WITH valid AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, ROUND(cost, 0) AS cost_rounded FROM shipments WHERE shipped_date > DATE '2023-05-08'), filtered AS (SELECT *, CASE WHEN cost_rounded >= 75 THEN 'High' WHEN cost_rounded >= 20 THEN 'Medium' ELSE 'Low' END AS cost_rounded_level FROM valid WHERE order_id IN (20, 31)), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY shipped_date DESC NULLS LAST, id ASC) AS rank_in_group FROM filtered) t WHERE rank_in_group = 1), ranked AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY order_id ORDER BY cost ASC) AS row_num FROM latest) t WHERE row_num = 1), with_dims AS (SELECT src.*, d.shipping_fee, d.channel, d.status FROM ranked src LEFT JOIN orders d ON src.order_id = d.id), stats AS (SELECT carrier, CASE WHEN cost >= 80 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, MIN(shipping_fee) AS min_shipping_fee, AVG(cost_rounded) AS avg_cost_rounded, SUM(CASE WHEN status = 'SHIPPED' THEN cost_rounded ELSE 0 END) AS shipped_cost_rounded, COUNT(CASE WHEN channel = 'mobile' THEN 1 END) AS mobile_count, SUM(cost) AS total_cost FROM with_dims GROUP BY carrier, CASE WHEN cost >= 80 THEN 'PREMIUM' ELSE 'STANDARD' END) SELECT carrier, cost_tier, min_shipping_fee, mobile_count, total_cost, CASE WHEN carrier RLIKE '^(UPS|DHL)$' THEN 'GROUP_A' WHEN carrier RLIKE '^(FedEx|Kerry)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS carrier_zone FROM stats ORDER BY carrier DESC NULLS LAST;
